// paintResult(): at full time the losing row dims (a draw dims nobody). Recomputed on every
// update, so a late score correction after the whistle repaints the right side.
function paintResult() {
  var root = document.querySelector('.scoreboard');
  var rowA = document.querySelector('.scoreboard-row-a');
  var rowB = document.querySelector('.scoreboard-row-b');
  var a = document.getElementById('f1');
  var b = document.getElementById('f3');
  if (!root || !rowA || !rowB || !a || !b) return;
  var final = root.classList.contains('scoreboard-final');
  var sa = parseInt(a.textContent, 10) || 0;
  var sb = parseInt(b.textContent, 10) || 0;
  rowA.classList.toggle('scoreboard-lose', final && sa < sb);
  rowB.classList.toggle('scoreboard-lose', final && sb < sa);
}

// paintWords(): copy the set-once words (f4 GOAL, f5 FULL TIME) into the tag and the strip.
// Safe to run any number of times; called on load, on every update and when a flag shows.
function paintWords() {
  var goal = document.getElementById('f4');
  var ft = document.getElementById('f5');
  var tags = document.querySelectorAll('.scoreboard-tag-word');
  for (var i = 0; i < tags.length; i++) if (goal) tags[i].textContent = goal.textContent;
  var strip = document.querySelector('.scoreboard-status-word');
  if (strip && ft) strip.textContent = ft.textContent;
}''')
